if(ai.system_sources)h+="<div style='padding:5px 10px;background:var(--ybg);border:1px solid rgba(255,196,0,.2);border-radius:6px;font-size:10px'>Sources: <strong>"+ai.system_sources.join(" + ")+"</strong></div>";
