// Typed Crypto measurements: missing values do not imply neutral readings.
function cryptoScalar(value,low,high){return typeof value==="number"&&Number.isFinite(value)&&(low==null||value>=low)&&(high==null||value<=high)?value:null;}
function cryptoText(value,fallback){return typeof value==="string"&&value.trim()&&value.length<=2000?value.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;"):(fallback||"Unavailable");}
function cryptoUnavailable(){return "<span class='crypto-value-unavailable' style='color:var(--t2)'>Unavailable</span>";}
function cryptoFearGauge(value,label,color){return cryptoScalar(value,0,100)==null?cryptoUnavailable():gauge(value,100,cryptoText(label),color);}
function cryptoScoreCircle(value){
 var score=cryptoScalar(value,0,100),color=score==null?"var(--t2)":score>=60?"var(--green)":score>=40?"var(--yellow)":"var(--red)";
 return "<div class='crypto-score-circle' style='min-width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;border:2px solid "+color+";color:"+color+"' title='Reported score; predictive meaning unverified'>"+(score==null?"N/A":score)+"</div>";
}
function cryptoIndicatorBars(ind){
 ind=ind&&typeof ind==="object"&&!Array.isArray(ind)?ind:{};
 var items=[["RSI",cryptoScalar(ind.rsi,0,100),"var(--yellow)"],["BB%",cryptoScalar((ind.bollinger||{}).position),"var(--blue)"],["StRSI",cryptoScalar((ind.stochrsi||{}).k,0,100),"var(--purple)"]];
 return items.map(function(x){
  var color=x[0]==="RSI"&&x[1]!=null?(x[1]<30?"var(--green)":x[1]>70?"var(--red)":x[2]):x[2];
  var h="<div class='crypto-indicator' style='margin-bottom:3px;overflow-wrap:anywhere'><span style='font-size:10px;color:var(--t2);display:inline-block;width:40px'>"+x[0]+"</span>";
  if(x[1]==null)return h+cryptoUnavailable()+"</div>";
  var width=Math.max(0,Math.min(x[1],100));
  return h+"<span title='Display width clipped to 0–100; reported value is shown alongside' style='display:inline-block;width:70px;height:5px;background:var(--bg4);border-radius:3px;vertical-align:middle'><span class='crypto-indicator-fill' style='display:block;height:100%;width:"+width+"%;background:"+color+";border-radius:3px'></span></span> <span class='mono' style='font-size:10px'>"+x[1]+"</span></div>";
 }).join("");
}
function cryptoDominance(value){
 var btc=cryptoScalar(value.btc_dominance,0,100),eth=cryptoScalar(value.eth_dominance,0,100),valid=btc!=null&&eth!=null&&btc+eth<=100;
 var h="<div class='card crypto-dominance' style='margin-bottom:12px;overflow-wrap:anywhere'><div class='card-title'>Reported dominance</div><p>BTC: "+(btc==null?"Unavailable":btc+"%")+" · ETH: "+(eth==null?"Unavailable":eth+"%")+"</p>";
 if(valid){var remainder=100-btc-eth;h+="<div role='img' aria-label='BTC "+btc+"%, ETH "+eth+"%, calculated remainder "+remainder+"%' style='display:flex;height:12px;border-radius:6px;overflow:hidden;margin:12px 0'><div style='width:"+btc+"%;background:var(--orange)'></div><div style='width:"+eth+"%;background:var(--blue)'></div><div style='width:"+remainder+"%;background:var(--bg4)'></div></div><p>Calculated remainder (100 − BTC − ETH): "+remainder+"%</p>";}
 else h+="<p>Combined breakdown unavailable.</p>";
 return h+"<p style='color:var(--t2);font-size:11px'>Common observation time and market universe unverified.</p></div>";
}

// Typed commentary presentation:

var fundingRaw=cryptoScalar(fn.avg_funding),mvrvRaw=cryptoScalar(onr.mvrv_approx,0);
var sentItems=[{n:"Fear & Greed",v:fgv,c:fgClr},{n:"Funding display (50 + rate × 500, clamped)",v:fundingRaw==null?null:Math.min(100,Math.max(0,50+fundingRaw*500)),c:"var(--blue)"},{n:"BTC Dominance (%)",v:dominance,c:"var(--orange)"},{n:"Stablecoin category (inflow 75, outflow 25, neutral 50)",v:st.net_signal==="INFLOW"?75:st.net_signal==="OUTFLOW"?25:st.net_signal==="NEUTRAL"?50:null,c:"var(--blue)"},{n:"MVRV display (ratio × 30, capped at 100)",v:mvrvRaw==null?null:Math.min(100,mvrvRaw*30),c:"var(--blue)"}];
