function cryptoMarketCapRatio(ratios){
 var m=ratios&&ratios.market_cap_extension;
 if(!m||m.contract!=="btc-market-cap-to-returned-mean.v1"||m.status!=="descriptive"||m.unit!=="ratio")return null;
 if(m.calls_eligible!==false||m.sizing_eligible!==false||m.execution_eligible!==false||m.forecast_qualified!==false||m.independent_investment_votes!==0)return null;
 return typeof m.value==="number"&&Number.isFinite(m.value)&&m.value>=0?m.value:null;
}
function cryptoMarketCapText(ratios){
 var value=cryptoMarketCapRatio(ratios);
 return value==null?"Unavailable":(value!==0&&(value<0.001||value>=1e9)?value.toExponential(4):String(Math.round(value*10000)/10000))+"×";
}
function cryptoMarketCapCard(ratios){
 var value=cryptoMarketCapRatio(ratios),m=ratios&&ratios.market_cap_extension||{},n=m.numerator||{},d=m.denominator||{},w=m.observation_window||{};
 function number(v){return typeof v==="number"&&Number.isFinite(v)&&v>=0?String(v):"Unavailable";}
 function date(v){return typeof v==="string"&&/^\d{4}-\d{2}-\d{2}T[0-9:.+-]+$/.test(v)&&Number.isFinite(Date.parse(v))?cryptoText(v):"Unavailable";}
 var h="<div class='card crypto-market-cap-card' style='overflow-wrap:anywhere'><div class='card-title'>BTC Market Cap / Returned Mean</div><div class='stat-big'>"+cryptoMarketCapText(ratios)+"</div><p style='font-size:12px;color:var(--t2)'>Descriptive comparison. MVRV is unavailable: this source has no realized capitalization. No valuation or investment vote.</p>";
 h+="<details style='margin-top:12px'><summary>Calculation and source</summary><p>Latest returned market cap ÷ arithmetic mean of all returned observations. The requested 365-day window does not establish daily sampling.</p>";
 if(value!=null)h+="<dl><dt>Numerator (USD)</dt><dd>"+number(n.value_usd)+"</dd><dt>Denominator (USD)</dt><dd>"+number(d.value_usd)+"</dd><dt>Returned observations</dt><dd>"+(Number.isSafeInteger(d.count)&&d.count>=30?d.count:"Unavailable")+"</dd><dt>First observation</dt><dd>"+date(w.first)+"</dd><dt>Last observation</dt><dd>"+date(w.last)+"</dd></dl>";
 h+="<p>Series: blockchain.info:market-cap · <a href='https://www.blockchain.com/explorer/charts/market-cap' target='_blank' rel='noopener noreferrer'>Source chart</a>. Original HTTP bytes, first-release timing and observation freshness are unverified.</p></details></div>";
