function cryptoFundingDenied(v){return v&&typeof v==='object'&&v.calls_eligible===false&&v.sizing_eligible===false&&v.execution_eligible===false&&v.forecast_qualified===false&&v.independent_investment_votes===0;}
function cryptoFundingDecimal(token,shift){
 if(typeof token!=='string'||token.length>128)return null;
 var m=/^(-?)(0|[1-9][0-9]*)(?:\.([0-9]+))?(?:[eE]([+-]?[0-9]+))?$/.exec(token);if(!m)return null;
 var digits=(m[2]+(m[3]||'')).replace(/^0+/,'');if(!digits)return '0';
 var trailing=(digits.match(/0+$/)||[''])[0].length,exponent=BigInt(m[4]||'0')-BigInt((m[3]||'').length)+BigInt(trailing)+BigInt(shift||0);
 return m[1]+digits.slice(0,digits.length-trailing)+'e'+exponent.toString();
}
function cryptoFundingPoint(row){
 if(!cryptoFundingDenied(row)||row.contract!=='crypto-reported-funding-point.v1'||row.status!=='descriptive')return null;
 if(['BTC','ETH','SOL','XRP','DOGE','ADA','AVAX','LINK','DOT','BNB'].indexOf(row.symbol)<0||['okx','bybit'].indexOf(row.provider)<0)return null;
 if(row.instrument!==row.symbol+(row.provider==='okx'?'-USDT-SWAP':'USDT')||row.unit!=='ratio_per_reported_funding_event'||row.annualized_pct!==null)return null;
 if(row.rate_basis!==(row.provider==='okx'?'current_endpoint_rate':'last_settled_history_rate')||row.source_timing_qualified!==false||row.cross_contract_comparability_verified!==false)return null;
 var rate=cryptoScalar(row.funding_rate),percent=cryptoScalar(row.funding_rate_pct);
 if(rate==null||percent==null||cryptoFundingDecimal(row.funding_rate_decimal)!==cryptoFundingDecimal(String(rate))||cryptoFundingDecimal(row.funding_rate_pct_decimal)!==cryptoFundingDecimal(String(percent))||cryptoFundingDecimal(row.funding_rate_decimal,2)!==cryptoFundingDecimal(row.funding_rate_pct_decimal))return null;
 if(typeof row.reported_settlement_at!=='string'||!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,6})?(?:\+00:00|Z)$/.test(row.reported_settlement_at)||!Number.isFinite(Date.parse(row.reported_settlement_at)))return null;
 if(row.funding_payment_direction!==(rate>0?'longs_pay_shorts':rate<0?'shorts_pay_longs':'zero_reported_rate'))return null;
 return row;
}
function cryptoFundingRows(packet){
 if(!cryptoFundingDenied(packet)||packet.contract!=='crypto-reported-funding.v1'||!Array.isArray(packet.rates))return [];
 var rows=packet.rates.map(cryptoFundingPoint).filter(Boolean),seen={};
 for(var row of rows){var identity=row.provider+':'+row.instrument;if(seen[identity])return [];seen[identity]=true;}
 return rows;
}
function cryptoFundingTable(packet){
 var rows=cryptoFundingRows(packet),typed=cryptoFundingDenied(packet)&&packet.contract==='crypto-reported-funding.v1';
 var h="<section class='card crypto-funding-card' style='overflow-wrap:anywhere'><div class='card-title'>Funding by reported event</div><p style='font-size:12px;color:var(--t2)'>Current endpoint rates and last settled history rates are different observations. Source timing, settlement periods and cross-contract comparability remain unqualified. No annual yield, leverage score or investment vote.</p>";
 h+="<p style='font-size:12px'>"+rows.length+" typed descriptive observations displayed. This is the requested universe, not global market coverage.</p>";
 if(rows.length){
  h+="<div tabindex='0' role='region' aria-label='Funding observations; scroll horizontally for source and settlement details' style='overflow-x:auto;max-width:100%'><table style='min-width:760px'><thead><tr><th>Contract / source</th><th>Rate per reported event</th><th>Payment direction</th><th>Basis / reported settlement (UTC)</th></tr></thead><tbody>";
  rows.forEach(function(row){
   h+="<tr><td class='mono'>"+esc(row.instrument)+"<br>"+esc(row.provider.toUpperCase())+"</td><td class='mono'>"+esc(row.funding_rate_pct_decimal)+"%</td><td>"+esc(row.funding_payment_direction.replace(/_/g,' '))+"</td><td>"+esc(row.rate_basis.replace(/_/g,' '))+"<br>"+esc(row.reported_settlement_at)+"</td></tr>";
  });h+="</tbody></table></div>";
 }else h+="<p>Unavailable — no typed funding observation. Legacy averages and annualized values are not substituted.</p>";
 h+="<details style='margin-top:12px;font-size:12px;line-height:1.6'><summary style='cursor:pointer'>Inspect collection coverage and source evidence</summary>";
 if(typed&&Array.isArray(packet.rates)){
  h+="<ul>";packet.rates.forEach(function(row){
   if(!row||typeof row!=='object')return;
   var valid=cryptoFundingPoint(row),ix=row.evidence_index,evidence=Number.isSafeInteger(ix)&&ix>=0&&Array.isArray(packet.source_attempts)?packet.source_attempts[ix]:null;
   h+="<li>"+esc(typeof row.instrument==='string'?row.instrument:'Unknown contract')+": "+(valid?'Descriptive observation':'Unavailable')+". ";
   if(!valid)h+=esc(typeof row.reason==='string'?row.reason:'Schema or value validation failed')+". ";
   var hash=evidence&&typeof evidence.original_response_sha256==='string'&&/^[a-f0-9]{64}$/.test(evidence.original_response_sha256)?evidence.original_response_sha256:null;
   h+=(evidence&&evidence.response_complete===true&&hash?"Complete response retained; SHA-256 <code>"+esc(hash)+"</code>.":"Complete source response not established.");
   if(evidence&&typeof evidence.acquired_completed_at==='string')h+=" Acquired: "+esc(evidence.acquired_completed_at)+".";
   h+="</li>";
  });h+="</ul>";
 }
 h+="<p>The packet retains received response bytes in source_attempts. A hash identifies those bytes; it does not authenticate the provider or establish freshness. Failed and bounded captures are marked incomplete. Fallback history remains separate from current endpoint observations.</p><p><a href='https://www.okx.com/docs-v5/en/#public-data-rest-api-get-funding-rate' target='_blank' rel='noopener noreferrer'>OKX funding definition</a> · <a href='https://bybit-exchange.github.io/docs/v5/market/history-fund-rate' target='_blank' rel='noopener noreferrer'>Bybit history definition</a></p></details></section>";
 return h;
}

